package blockbranch.realistic;

import java.util.*;
import com.mojang.serialization.*;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.biome.*;
import net.minecraft.world.level.levelgen.RandomState;
import net.minecraft.world.level.levelgen.structure.placement.StructurePlacement;

/** Saved definitions share placement: 2 changes jungle stonework; 3 adds sanctuary stonework; 4 adds crypt stonework; 5 adds mansion perimeter architecture; 7 replaces jungle architecture; 8 replaces pyramid architecture; 9 replaces crypt architecture. */
public final class ReimaginedSites {
 public static final int CRYPT=1,PYRAMID=2,JUNGLE=3,MANSION=4,MONUMENT=5;
 private record Cache(long seed,int[] rows,String hash){static final Codec<Cache> CODEC=RecordCodecBuilder.create(i->i.group(Codec.LONG.fieldOf("seed").forGetter(Cache::seed),Codec.INT_STREAM.xmap(s->s.limit(131073).toArray(),Arrays::stream).fieldOf("rows").forGetter(Cache::rows),Codec.STRING.fieldOf("hash").forGetter(Cache::hash)).apply(i,Cache::new));}
 public static final Codec<ReimaginedSites> CODEC=RecordCodecBuilder.create(i->i.group(Codec.INT.validate(v->StructureGenerationSchema.supportedLayout(v)?DataResult.success(v):DataResult.error(()->"Unsupported reimagined layout definition")).fieldOf("definition").forGetter(v->v.definition),Cache.CODEC.lenientOptionalFieldOf("region_cache").forGetter(v->v.cache.filter(c->c.rows.length<=131072))).apply(i,ReimaginedSites::new));
 private final int definition;private final Optional<Cache> cache;private final Int2ObjectOpenHashMap<Region> cells=new Int2ObjectOpenHashMap<>();private List<Region> regions=List.of();private long seed;private RealisticGenerator.HutPlanningTerrain terrain;private BiomeResolver surface;
 public ReimaginedSites(){this(1,Optional.empty());}private ReimaginedSites(int definition,Optional<Cache> c){this.definition=definition;cache=c;}public int definition(){return definition;}
 public record Plan(int kind,int x,int y,int z,int region,int caveDirection,long seed){public BlockPos center(){return new BlockPos(x,y,z);}public int radius(){return ReimaginedSites.radius(kind);}}
 public static int radius(int kind){return switch(kind){case CRYPT->32;case PYRAMID->42;case JUNGLE->38;case MANSION->100;case MONUMENT->48;default->throw new IllegalArgumentException("Unknown reimagined kind");};}
 boolean valid(long s){if(cache.isEmpty())return false;var c=cache.get();if(c.seed!=s||c.rows.length>131072||c.rows.length%5!=0||!hash(s,c.rows).equals(c.hash))return false;var seen=new HashSet<Integer>();for(int i=0;i<c.rows.length;i+=5){if(c.rows[i]<1||c.rows[i]>5)return false;for(int j=1;j<=4;j++)if(c.rows[i+j]<0||c.rows[i+j]>=4194304||!seen.add(c.rows[i+j]))return false;}return true;}
 ReimaginedSites bind(long s,RealisticGenerator g,RandomState random){check();var field=g.hutPlanningTerrain(random);var climate=field.climate();int[] rows;
  if(valid(s))rows=cache.get().rows;else{var atlas=StructureRegionAtlas.labeled(s,(x,z)->label(s,x,z,field.drainage(),climate));int[] keys=atlas.substantialOwnerIndices(),p=atlas.candidateIndices(keys,4);rows=new int[keys.length*5];for(int i=0;i<keys.length;i++){int cell=p[i*4];rows[i*5]=label(s,(cell%2048-1024)*2048+1024,(cell/2048-1024)*2048+1024,field.drainage(),climate);System.arraycopy(p,i*4,rows,i*5+1,4);}}
  var out=new ReimaginedSites(definition,Optional.of(new Cache(s,rows,hash(s,rows))));out.seed=s;out.terrain=field;out.surface=((ScreeBiomeSource)g.getBiomeSource()).surfaceResolver();var all=new ArrayList<Region>();for(int i=0;i<rows.length;i+=5){var region=out.new Region(rows[i],Arrays.copyOfRange(rows,i+1,i+5));all.add(region);for(int cell:region.selected)if(out.cells.put(cell,region)!=null)throw new IllegalArgumentException("Repeated regional candidate");}out.regions=List.copyOf(all);check();return out;
 }
 private static int label(long seed,int x,int z,DrainageNetwork d,ClimateField climate){long p=d.structureClimatePacked(x,z);int height=(int)(p>>32);var c=climate.structureSample(x,z,d);double t=c.meanTemperatureC(),m=c.moisture();if((p&3)==3)return height< -136?MONUMENT:0;if((p&1)!=0)return 0;if(t>=10&&t<=30&&m<.12)return PYRAMID;if(t>23&&m>=.65)return JUNGLE;if(t>=6&&t<=23&&m>=.6&&BirchForest.province(seed^0x4441524B464F5245L,x,z)>.45)return MANSION;if(t>=6&&t<=23&&m>=.27&&m<.65)return CRYPT;return 0;}
 private static int cell(int x,int z){int cx=Math.floorDiv(x,2048)+1024,cz=Math.floorDiv(z,2048)+1024;return cx<0||cx>=2048||cz<0||cz>=2048?-1:cz*2048+cx;}
 private long proposal(int cell,int n){long h=OakBirchWoodland.mix(seed^0x5245494D4147494EL^((long)cell<<8)^n);int x=Math.floorDiv((cell%2048-1024)*2048+1024+(int)Math.floorMod(h,1536)-768,16)*16+8,z=Math.floorDiv((cell/2048-1024)*2048+1024+(int)Math.floorMod(h>>>24,1536)-768,16)*16+8;return((long)x<<32)|(z&0xffffffffL);}
 public Optional<Plan> forStart(int kind,int cx,int cz){int x=cx*16+8,z=cz*16+8;if(Math.abs((long)x)>2097000||Math.abs((long)z)>2097000)return Optional.empty();var r=cells.get(cell(x,z));if(r==null||r.kind!=kind)return Optional.empty();long q=((long)x<<32)|(z&0xffffffffL);boolean possible=false;for(int n=0;n<64;n++)if(proposal(cell(x,z),n)==q){possible=true;break;}return possible?r.plan().filter(p->p.x>>4==cx&&p.z>>4==cz):Optional.empty();}
 public StructurePlacement placement(int kind){return new StructurePlacement(){public boolean isStructureChunk(net.minecraft.world.level.chunk.ChunkGeneratorStructureState s,int x,int z){return forStart(kind,x,z).isPresent();}public MapCodec<? extends StructurePlacement> codec(){return MapCodec.unit(this);}public BlockPos getLocatePos(ChunkPos p){return forStart(kind,p.x(),p.z()).map(Plan::center).orElse(new BlockPos(p.getMinBlockX()+8,64,p.getMinBlockZ()+8));}};}
 public List<Region> ordered(int kind,BlockPos origin,double range){var out=new ArrayList<Region>();for(var r:regions)if(r.kind==kind&&r.lower(origin)<=range)out.add(r);out.sort(Comparator.comparingDouble((Region r)->r.lower(origin)).thenComparingInt(Region::owner));return out;}
 public int regionCount(int kind){return(int)regions.stream().filter(r->r.kind==kind).count();}
 public final class Region{private final int kind;private final int[] selected;private volatile Optional<Plan> result;private Region(int kind,int[] selected){this.kind=kind;this.selected=selected;}public int kind(){return kind;}public int owner(){return selected[0];}public double lower(BlockPos o){double best=Double.POSITIVE_INFINITY;for(int c:selected){int x=(c%2048-1024)*2048+1024,z=(c/2048-1024)*2048+1024;best=Math.min(best,Math.hypot(Math.max(0,Math.abs((long)o.getX()-x)-776),Math.max(0,Math.abs((long)o.getZ()-z)-776)));}return Math.max(0,Math.nextDown(best));}public synchronized Optional<Plan> plan(){check();if(result!=null)return result;var made=build(this);check();return result=made;}}
 private boolean biome(int kind,int x,int z){var b=surface.getNoiseBiome(x>>2,0,z>>2);return switch(kind){case CRYPT->b.is(Biomes.FOREST)||b.is(Biomes.BIRCH_FOREST)||b.is(Biomes.PLAINS);case PYRAMID->b.is(Biomes.DESERT);case JUNGLE->b.is(Biomes.JUNGLE)||b.is(Biomes.BAMBOO_JUNGLE);case MANSION->b.is(Biomes.DARK_FOREST);case MONUMENT->b.is(Biomes.DEEP_OCEAN)||b.is(Biomes.DEEP_COLD_OCEAN)||b.is(Biomes.DEEP_FROZEN_OCEAN)||b.is(Biomes.DEEP_LUKEWARM_OCEAN);default->false;};}
 private Optional<Plan> build(Region r){var d=terrain.drainage();int radius=radius(r.kind);long salt=OakBirchWoodland.mix(seed^((long)r.kind<<48)^r.owner());for(int cell:r.selected)for(int n=0;n<64;n++){check();long q=proposal(cell,n);int x=(int)(q>>32),z=(int)q;if(!biome(r.kind,x,z))continue;int min=Integer.MAX_VALUE,max=Integer.MIN_VALUE;boolean good=true;int relief=r.kind==CRYPT?20:r.kind==MONUMENT?32:r.kind==MANSION?8:10;
   outer:for(int dz=-radius;dz<=radius;dz+=Math.max(1,radius/2))for(int dx=-radius;dx<=radius;dx+=Math.max(1,radius/2)){var s=d.sample(x+dx,z+dz);min=Math.min(min,s.height());max=Math.max(max,s.height());if((r.kind==MONUMENT?!d.oceanWater(x+dx,z+dz,s)||s.height()>20:s.waterLevel()!=DrainageNetwork.DRY)||max-min>relief){good=false;break outer;}}if(!good)continue;
   for(int[] p:new int[][]{{-radius,-radius},{radius,-radius},{-radius,radius},{radius,radius}})if(!biome(r.kind,x+p[0],z+p[1])){good=false;break;}if(!good)continue;
   // Complete terrain footprint; expensive work occurs only after all cheap rejections.
   outer:for(int dz=-radius;dz<=radius;dz++)for(int dx=-radius;dx<=radius;dx++){var s=d.sample(x+dx,z+dz);min=Math.min(min,s.height());max=Math.max(max,s.height());if((r.kind==MONUMENT?!d.oceanWater(x+dx,z+dz,s):s.waterLevel()!=DrainageNetwork.DRY)||max-min>relief){good=false;break outer;}}if(!good)continue;
   int y=r.kind==MONUMENT?max+1:r.kind==PYRAMID?min-6:max+1,dir=0;if(r.kind==CRYPT){good=false;var caves=new UndergroundStructure(seed);for(int depth=32;depth<=96&&!good;depth+=8)for(int k=0;k<4;k++){int dx=k==0?24:k==1?-24:0,dz=k==2?24:k==3?-24:0;int cy=min-depth;if(caves.voidAt(x+dx,cy+1,z+dz,d.sample(x+dx,z+dz).height())&&caves.voidAt(x+dx,cy+2,z+dz,d.sample(x+dx,z+dz).height())){y=cy;dir=k;good=true;break;}}if(!good)continue;}
   if(y<TerrainShape.FLOOR+64||y>TerrainShape.CEILING-160)continue;return Optional.of(new Plan(r.kind,x,y,z,r.owner(),dir,salt));
  }return Optional.empty();}
 private static String hash(long seed,int[] data){try{var b=java.nio.ByteBuffer.allocate(12+data.length*4).putInt(0x52454931).putLong(seed);for(int v:data)b.putInt(v);return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b.array()));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private static void check(){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("Reimagined regional planning interrupted before publication");}
}
